-- deployment: Creating PUBLIC.ORDER_ITEM_DETAILS...
CREATE VIEW PUBLIC.ORDER_ITEM_DETAILS AS SELECT
  oi.ORDER_ITEM_ID,
  oi.ORDER_ID,
  o.ORDER_DATE,
  o.STATUS,
  c.CUSTOMER_ID,
  c.CUSTOMER_NAME,
  c.SEGMENT,
  p.PRODUCT_ID,
  p.PRODUCT_NAME,
