);


-- deployment: Creating PUBLIC.SEGMENT_REVENUE_VS_TARGET...
CREATE VIEW PUBLIC.SEGMENT_REVENUE_VS_TARGET AS SELECT -- noqa: ST06
  DATE_TRUNC('MONTH', o.ORDER_DATE) AS TARGET_MONTH,
  c.SEGMENT,
  SUM(o.ORDER_TOTAL) AS ACTUAL_REVENUE,
  t.TARGET_REVENUE,
  SUM(o.ORDER_TOTAL) - t.TARGET_REVENUE AS REVENUE_VARIANCE
FROM PUBLIC.ORDERS o
INNER JOIN PUBLIC.CUSTOMERS c
  ON o.CUSTOMER_ID = c.CUSTOMER_ID
LEFT JOIN PUBLIC.MONTHLY_REVENUE_TARGETS t
  ON DATE_TRUNC('MONTH', o.ORDER_DATE) = t.TARGET_MONTH
 AND c.SEGMENT = t.SEGMENT
GROUP BY 1, 2, 4;


-- deployment: Creating PUBLIC.UPSERT_REVENUE_TARGET(DATE, VARCHAR, NUMBER)...
CREATE PROCEDURE PUBLIC.UPSERT_REVENUE_TARGET(P_TARGET_MONTH DATE, P_SEGMENT VARCHAR, P_TARGET_REVENUE NUMBER(10,2))
RETURNS VARCHAR(134217728)
LANGUAGE SQL
AS
$$
BEGIN
  MERGE INTO STEPHANIE_DEV.PUBLIC.MONTHLY_REVENUE_TARGETS t
  USING (
    SELECT :P_TARGET_MONTH AS TARGET_MONTH,
           :P_SEGMENT AS SEGMENT,
           :P_TARGET_REVENUE AS TARGET_REVENUE
  ) s
  ON t.TARGET_MONTH = s.TARGET_MONTH
 AND t.SEGMENT = s.SEGMENT
  WHEN MATCHED THEN UPDATE SET TARGET_REVENUE = s.TARGET_REVENUE
  WHEN NOT MATCHED THEN INSERT (TARGET_MONTH, SEGMENT, TARGET_REVENUE)
  VALUES (s.TARGET_MONTH, s.SEGMENT, s.TARGET_REVENUE);

  RETURN 'Revenue target upserted';
END;
$$;


